import fs from "node:fs";

const file = process.argv[2];
if (!file) { console.error("Usage: node patch-oasis-rofl-e2e.mjs <path-to-test.rs>"); process.exit(2); }
const source = fs.readFileSync(file, "utf8");
const anchor = "#[test]\nfn test_provider_management()";
if (source.split(anchor).length !== 2) throw new Error("Expected exactly one insertion point; refusing to patch unexpected source.");
const regressionTest = "#[test]\nfn test_expired_topup_charges_full_fee_and_stale_remove_can_delete_renewed_instance() {\n    let initial_time = 1_741_778_021;\n    let mut mock = mock::Mock {\n        epoch: 42,\n        runtime_header: Header {\n            timestamp: initial_time,\n            ..Default::default()\n        },\n        ..Default::default()\n    };\n    let ctx = mock.create_ctx_for_runtime::<TestRuntime>(true);\n    TestRuntime::migrate(&ctx);\n\n    let mut signer_alice = mock::Signer::new(0, keys::alice::sigspec());\n    let mut signer_charlie = mock::Signer::new(0, keys::charlie::sigspec());\n    let mut signer_dave = mock::Signer::new(0, keys::dave::sigspec());\n\n    // Create the provider's scheduler ROFL app.\n    let app_create = rofl::types::Create {\n        scheme: rofl::types::IdentifierScheme::CreatorNonce,\n        ..Default::default()\n    };\n    let dispatch_result = signer_alice.call(&ctx, \"rofl.Create\", app_create);\n    assert!(dispatch_result.result.is_success(), \"scheduler app creation should succeed\");\n    let scheduler_app: rofl::app_id::AppId =\n        cbor::from_value(dispatch_result.result.unwrap()).unwrap();\n\n    // Create a provider offering native monthly payments.\n    let provider_create = types::ProviderCreate {\n        nodes: vec![keys::bob::pk_ed25519().into()],\n        scheduler_app,\n        payment_address: types::PaymentAddress::Native(keys::dave::address()),\n        offers: vec![types::Offer {\n            payment: types::Payment::Native {\n                denomination: Denomination::NATIVE,\n                terms: BTreeMap::from([(types::Term::Month, 10_000)]),\n            },\n            resources: types::Resources {\n                tee: types::TeeType::TDX,\n                memory: 512,\n                cpus: 1,\n                storage: 1024,\n                gpu: None,\n            },\n            capacity: 1,\n            ..Default::default()\n        }],\n        metadata: Default::default(),\n    };\n    let dispatch_result = signer_alice.call(&ctx, \"roflmarket.ProviderCreate\", provider_create);\n    assert!(dispatch_result.result.is_success(), \"provider creation should succeed\");\n\n    // Register the scheduler app and authorize Dave's key.\n    let fake_registration = rofl::types::Registration {\n        app: scheduler_app,\n        extra_keys: vec![keys::dave::pk()],\n        ..Default::default()\n    };\n    rofl::state::update_registration(fake_registration.clone()).unwrap();\n\n    // Create a one-month instance as Charlie.\n    let instance_create = types::InstanceCreate {\n        provider: keys::alice::address(),\n        offer: 0.into(),\n        admin: None,\n        deployment: Some(Default::default()),\n        term: types::Term::Month,\n        term_count: 1,\n    };\n    let dispatch_result =\n        signer_charlie.call(&ctx, \"roflmarket.InstanceCreate\", instance_create);\n    assert!(dispatch_result.result.is_success(), \"instance creation should succeed\");\n    let instance_id: types::InstanceId =\n        cbor::from_value(dispatch_result.result.unwrap()).unwrap();\n\n    // Bind the scheduler app registration to the provider's authorized node.\n    let fake_registration = rofl::types::Registration {\n        node_id: keys::bob::pk_ed25519().into(),\n        ..fake_registration\n    };\n    rofl::state::update_registration(fake_registration).unwrap();\n\n    let accept = types::InstanceAccept {\n        provider: keys::alice::address(),\n        ids: vec![instance_id],\n        metadata: Default::default(),\n    };\n    let dispatch_result = signer_dave.call(&ctx, \"roflmarket.InstanceAccept\", accept);\n    assert!(dispatch_result.result.is_success(), \"provider scheduler should accept the instance\");\n\n    let instance: types::Instance = signer_alice\n        .query(\n            &ctx,\n            \"roflmarket.Instance\",\n            types::InstanceQuery {\n                provider: keys::alice::address(),\n                id: instance_id,\n            },\n        )\n        .unwrap();\n    assert_eq!(instance.status, types::InstanceStatus::Accepted);\n\n    let old_paid_until = instance.paid_until;\n    let topup_time = old_paid_until + 1_800;\n    let renewal_duration = 2 * types::Term::Month.as_secs();\n    let expected_fee = 20_000u128;\n    let payment_address = Address::from_eth(&instance.payment_address);\n    let tenant_balance_before =\n        Accounts::get_balance(keys::charlie::address(), Denomination::NATIVE).unwrap();\n    let payment_balance_before =\n        Accounts::get_balance(payment_address, Denomination::NATIVE).unwrap();\n    let provider_balance_before_claim =\n        Accounts::get_balance(keys::dave::address(), Denomination::NATIVE).unwrap();\n\n    // Move chain time 30 minutes beyond expiry, then dispatch the real runtime call.\n    mock.runtime_header.timestamp = topup_time;\n    let ctx = mock.create_ctx_for_runtime::<TestRuntime>(true);\n    let topup = types::InstanceTopUp {\n        provider: keys::alice::address(),\n        id: instance_id,\n        term: types::Term::Month,\n        term_count: 2,\n    };\n    let dispatch_result = signer_charlie.call(&ctx, \"roflmarket.InstanceTopUp\", topup);\n    assert!(\n        dispatch_result.result.is_success(),\n        \"InstanceTopUp should currently accept an expired-but-Accepted instance\"\n    );\n\n    let tenant_balance_after =\n        Accounts::get_balance(keys::charlie::address(), Denomination::NATIVE).unwrap();\n    let payment_balance_after =\n        Accounts::get_balance(payment_address, Denomination::NATIVE).unwrap();\n    assert_eq!(\n        tenant_balance_before - tenant_balance_after,\n        expected_fee,\n        \"tenant must be charged the complete two-month fee\"\n    );\n    assert_eq!(\n        payment_balance_after - payment_balance_before,\n        expected_fee,\n        \"instance payment address must receive the complete two-month fee\"\n    );\n\n    let renewed: types::Instance = signer_alice\n        .query(\n            &ctx,\n            \"roflmarket.Instance\",\n            types::InstanceQuery {\n                provider: keys::alice::address(),\n                id: instance_id,\n            },\n        )\n        .unwrap();\n    assert_eq!(renewed.status, types::InstanceStatus::Accepted);\n    assert_eq!(\n        renewed.paid_until,\n        old_paid_until + renewal_duration,\n        \"current implementation extends from the stale expiry timestamp\"\n    );\n    assert_eq!(\n        renewed.paid_until,\n        topup_time + renewal_duration - 1_800,\n        \"the paid term must remain 1,800 seconds shorter than a term starting now\"\n    );\n\n    // Claim payment after top-up. The claim calculation uses elapsed wall-clock time,\n    // so it includes the 1,800 seconds after the instance had already expired.\n    let claim = types::InstanceClaimPayment {\n        provider: keys::alice::address(),\n        instances: vec![instance_id],\n    };\n    let dispatch_result = signer_dave.call(&ctx, \"roflmarket.InstanceClaimPayment\", claim);\n    assert!(dispatch_result.result.is_success(), \"scheduler payment claim should succeed\");\n    let provider_balance_after_claim =\n        Accounts::get_balance(keys::dave::address(), Denomination::NATIVE).unwrap();\n    let provider_claim = provider_balance_after_claim - provider_balance_before_claim;\n    let total_escrow = payment_balance_before + expected_fee;\n    let paid_duration = renewed.paid_until - instance.paid_from;\n    let elapsed_including_expired_gap = topup_time - instance.paid_from;\n    let elapsed_before_expiry = old_paid_until - instance.paid_from;\n    let claim_with_gap =\n        (u128::from(elapsed_including_expired_gap) * total_escrow) / u128::from(paid_duration);\n    let claim_without_gap =\n        (u128::from(elapsed_before_expiry) * total_escrow) / u128::from(paid_duration);\n    assert_eq!(provider_claim, claim_with_gap, \"provider claim must include elapsed time after expiry\");\n    assert_eq!(provider_claim, 10_006, \"fixture should pay 10,006 units to the provider\");\n    assert_eq!(provider_claim - claim_without_gap, 6, \"the expired 1,800-second gap contributes 6 additional units to this claim\");\n    let remaining_after_claim =\n        Accounts::get_balance(payment_address, Denomination::NATIVE).unwrap();\n\n    // Simulate a stale scheduler removal job queued from the expired-state discovery.\n    // The on-chain remove handler does not re-check the expiry snapshot before deleting.\n    let remove = types::InstanceRemove {\n        provider: keys::alice::address(),\n        id: instance_id,\n    };\n    let dispatch_result = signer_dave.call(&ctx, \"roflmarket.InstanceRemove\", remove);\n    assert!(dispatch_result.result.is_success(), \"a stale remove call should still succeed after the instance was topped up\");\n\n    let tenant_balance_after_remove =\n        Accounts::get_balance(keys::charlie::address(), Denomination::NATIVE).unwrap();\n    let payment_balance_after_remove =\n        Accounts::get_balance(payment_address, Denomination::NATIVE).unwrap();\n    assert_eq!(tenant_balance_after_remove, tenant_balance_after + remaining_after_claim, \"removal should refund only the remaining escrow after the provider claim\");\n    assert_eq!(payment_balance_after_remove, 0, \"payment address should be emptied by the refund\");\n    let removed: Result<types::Instance, _> = signer_alice.query(\n        &ctx,\n        \"roflmarket.Instance\",\n        types::InstanceQuery {\n            provider: keys::alice::address(),\n            id: instance_id,\n        },\n    );\n    assert!(removed.is_err(), \"the newly topped-up instance should nevertheless be removed\");\n}";
fs.writeFileSync(file, source.replace(anchor, regressionTest + "\n\n" + anchor));

// Match the test-only SDK feature used by sibling modules (contracts and EVM).
const manifest = file.replace(/src\/test\.rs$/, "Cargo.toml");
const manifestContent = fs.readFileSync(manifest, "utf8");
if (!manifestContent.includes('[dev-dependencies]')) {
  fs.writeFileSync(manifest, manifestContent.trimEnd() + '\n\n[dev-dependencies]\noasis-runtime-sdk = { path = "../..", features = ["test"] }\n');
} else if (!manifestContent.includes('oasis-runtime-sdk = { path = "../..", features = ["test"] }')) {
  throw new Error("Unexpected dev-dependencies section; refusing to rewrite the manifest automatically.");
}
console.log("Injected the isolated runtime regression test and enabled SDK test helpers.");
